#!/usr/bin/env bash
# make-fixtures.sh: build the adversarial metadata fixture corpus for MetadataScrubber.
#
# Every picture is synthetic (gradients, shapes and seeded noise). Every name,
# serial number and ID is invented. GPS positions are public landmarks.
#
# Each metadata location carries a unique planted string, either a canary of the
# form CANARY-<FIXTURE>-<PLACE>-<4 hex> or a plausible marker value such as a
# date. The registry of every planted string, with the tier the spec expects,
# is written to out/canaries.tsv and documented in CANARIES.md.
#
# Needs: exiftool, ImageMagick 7 (magick, with HEIC and WebP), python3 and GNU
# coreutils and findutils (sha1sum, stat -c, find -printf).
# Uses ffmpeg for the motion photo video when present; otherwise a hand-built
# MP4 with the same planted strings. Set FIXTURES_NO_FFMPEG=1 to force that.
#
# Reproducible: no clocks, all noise seeded, single-threaded ImageMagick. The
# same tool versions give byte-identical output (see out/SHA256SUMS).
#
# Usage: tests/fixtures/make-fixtures.sh
# Output: tests/fixtures/out/ (git-ignored), plus out/canaries.tsv,
#         out/exiftool-visibility.tsv, out/exiftool/<fixture>.txt,
#         out/canaries-tables.md and out/SHA256SUMS.

set -euo pipefail
export LC_ALL=C TZ=UTC MAGICK_THREAD_LIMIT=1 OMP_NUM_THREADS=1

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
OUT="$HERE/out"
W="$OUT/.work"
KIT="$HERE/fixturekit.py"
REG="$OUT/canaries.tsv"

for tool in exiftool magick python3; do
  command -v "$tool" >/dev/null || { echo "make-fixtures: $tool is required" >&2; exit 1; }
done
# The list is read whole first: grep -q stops reading early, and with pipefail the
# magick that gets cut off would fail the check.
FORMATS=$(magick -list format)
for fmt in HEIC WEBP; do
  grep -qE "^ *$fmt\*? " <<<"$FORMATS" || { echo "make-fixtures: magick lacks $fmt support" >&2; exit 1; }
done
USE_FFMPEG=0
if [ -z "${FIXTURES_NO_FFMPEG:-}" ] && command -v ffmpeg >/dev/null; then USE_FFMPEG=1; fi

# Start clean, but keep the .gitignore that stops generated binaries being committed.
mkdir -p "$OUT"
find "$OUT" -mindepth 1 -maxdepth 1 ! -name .gitignore -exec rm -rf {} +
printf '%s\n' '# Everything in this folder is generated by ../make-fixtures.sh. Do not commit it.' '*' '!.gitignore' > "$OUT/.gitignore"
mkdir -p "$W"

kit() { python3 "$KIT" "$@"; }

# Registry. canary NAME FILE LOCATION GROUP TIER BASIS [STORED_AS]
#   prints CANARY-NAME-xxxx, where xxxx is the start of the SHA-1 of NAME.
# marker VALUE FILE LOCATION GROUP TIER BASIS [STORED_AS]
#   registers a plausible value (a date, a coordinate string) and prints it.
# BASIS is "spec" when the spec names the item and its tier, "inferred" when
# the spec is silent and the tier follows the closest rule in it.
# STORED_AS is raw (verbatim bytes), zlib (inside a compressed PNG chunk),
# hex (inside a PNG raw profile) or utf16 (UTF-16 text, as Ducky stores it).
# A marker may add EXIFTOOL_FORM, "Group|Tag Name|value", for values exiftool
# prints in another format (dates, coordinates), so the visibility check can
# tell "shown, reformatted" from "not shown".
printf 'string\tkind\tfile\tlocation\tgroup\ttier\tbasis\tencoding\texiftool_form\n' > "$REG"
canary() {
  local s
  s="CANARY-$1-$(printf '%s' "$1" | sha1sum | cut -c1-4)"
  printf '%s\tcanary\t%s\t%s\t%s\t%s\t%s\t%s\t\n' "$s" "$2" "$3" "$4" "$5" "$6" "${7:-raw}" >> "$REG"
  printf '%s' "$s"
}
marker() {
  printf '%s\tmarker\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$1" "$2" "$3" "$4" "$5" "$6" "${7:-raw}" "${8:-}" >> "$REG"
  printf '%s' "$1"
}

# exiftool wrapper: any warning or error stops the build.
CFG="$W/exiftool.config"
cat > "$CFG" <<'EOF'
# Lets the fixture builder write tags that exiftool would not write on its own:
# a raw MakerNote and two private tags with IDs no standard assigns.
%Image::ExifTool::UserDefined = (
  'Image::ExifTool::Exif::Main' => {
    0x927c => { Name => 'FixtureMakerNote',   Writable => 'undef',  WriteGroup => 'ExifIFD' },
    0xbeef => { Name => 'FixturePrivateIFD0', Writable => 'string', WriteGroup => 'IFD0' },
    0xbef0 => { Name => 'FixturePrivateExif', Writable => 'string', WriteGroup => 'ExifIFD' },
  },
);
1;
EOF
# Tags every camera writes. Without them exiftool creates ColorSpace
# "Uncalibrated" and copies the JFIF density (1 x 1, no unit) into IFD0.
cat > "$W/common.args" <<'EOF'
-XResolution=72
-YResolution=72
-ResolutionUnit=inches
-ExifIFD:ColorSpace#=1
EOF
et() {
  local err
  if ! err=$(exiftool -config "$CFG" -overwrite_original "$@" 2>&1 >/dev/null); then
    echo "make-fixtures: exiftool failed: $err" >&2; exit 1
  fi
  if [ -n "$err" ]; then echo "make-fixtures: exiftool warned: $err" >&2; exit 1; fi
}

# A colour profile from the system. Display P3 if one is installed, else sRGB.
ICC_SRC=""
for p in /usr/share/color/icc/*/*[Pp]3*.ic[cm] /usr/share/color/icc/colord/sRGB.icc /usr/share/color/icc/ghostscript/srgb.icc; do
  if [ -f "$p" ]; then ICC_SRC="$p"; break; fi
done
[ -n "$ICC_SRC" ] || { echo "make-fixtures: no ICC profile found under /usr/share/color/icc" >&2; exit 1; }

# Scenes. Drawn shapes only, no text, so fonts cannot change the output.
scene() { # OUT WIDTH HEIGHT SEED SKY GROUND
  local w=$2 h=$3
  magick -size "${w}x${h}" "gradient:$5-#f3e2c0" \
    -fill "$6" -draw "rectangle 0,$((h * 2 / 3)) $((w - 1)),$((h - 1))" \
    -fill '#f7d046' -draw "circle $((w / 5)),$((h / 5)) $((w / 5 + w / 17)),$((h / 5))" \
    -fill '#8b5a2b' -draw "rectangle $((w * 35 / 100)),$((h * 47 / 100)) $((w * 58 / 100)),$((h * 69 / 100))" \
    -fill '#b23a2e' -draw "polygon $((w * 33 / 100)),$((h * 47 / 100)) $((w * 465 / 1000)),$((h / 3)) $((w * 60 / 100)),$((h * 47 / 100))" \
    -seed "$4" -attenuate 0.25 +noise Gaussian -alpha off "$1"
}
jpg() { magick "$1" -strip -quality "${3:-90}" -sampling-factor 2x2 "$2"; }

echo "make-fixtures: ICC source $ICC_SRC; ffmpeg $([ "$USE_FFMPEG" = 1 ] && echo yes || echo no)"

# 1. jpeg-everything.jpg ######################################################
F=jpeg-everything.jpg
# The original scene has a red figure on the right. The main image is cropped
# so the figure is gone; both embedded previews still show it.
scene "$W/e-orig.png" 1200 900 11 '#9cc8ef' '#3f6b35'
magick "$W/e-orig.png" -fill '#e0301e' -draw 'circle 1060,500 1060,600' \
  -fill '#ffffff' -draw 'circle 1035,475 1035,488' -draw 'circle 1085,475 1085,488' "$W/e-orig.png"
magick "$W/e-orig.png" -crop 880x660+0+120 +repage "$W/e-main.png"
jpg "$W/e-main.png" "$W/e.jpg" 90
magick "$W/e-orig.png" -resize 160x120 -strip -quality 80 "$W/e-thumb.jpg"
et -Comment="$(canary JPEG-THUMB-COM "$F" 'EXIF IFD1 thumbnail (uncropped original), COM inside it' hidden red spec)" "$W/e-thumb.jpg"
magick "$W/e-orig.png" -resize 128x96 -strip -quality 75 "$W/e-psthumb.jpg"
et -Comment="$(canary JPEG-PSTHUMB-COM "$F" 'Photoshop IRB thumbnail (uncropped original), COM inside it' hidden red spec)" "$W/e-psthumb.jpg"
kit icc "$ICC_SRC" "$W/e.icc" "$(canary JPEG-ICC-PRIVATE "$F" 'ICC profile (APP2), private CNRY text tag' hidden red spec)"
kit blob "$W/e-makernote.bin" 240 7 "$(canary JPEG-EXIF-MAKERNOTE "$F" 'EXIF MakerNote (binary)' hidden red inferred)" 'FJORDCAM II'
cat > "$W/e.args" <<EOF
-ExifByteOrder=II
-Make=Fjordcam $(canary JPEG-EXIF-MAKE "$F" 'EXIF IFD0 Make' device amber spec)
-Model=F7 Pro $(canary JPEG-EXIF-MODEL "$F" 'EXIF IFD0 Model' device amber spec)
-Software=FjordOS 14.2.1 $(canary JPEG-EXIF-SOFTWARE "$F" 'EXIF IFD0 Software' device amber spec)
-Artist=Astrid Holmvik $(canary JPEG-EXIF-ARTIST "$F" 'EXIF IFD0 Artist' who red spec)
-Copyright=Copyright 2024 Astrid Holmvik $(canary JPEG-EXIF-COPYRIGHT "$F" 'EXIF IFD0 Copyright' who red spec)
-ImageDescription=Picnic below the tower $(canary JPEG-EXIF-DESCRIPTION "$F" 'EXIF IFD0 ImageDescription' hidden red inferred)
-ModifyDate=$(marker '2024:06:15 18:02:11' "$F" 'EXIF IFD0 DateTime (ModifyDate)' when amber spec)
-HostComputer=Astrid-Laptop $(canary JPEG-EXIF-HOSTCOMPUTER "$F" 'EXIF IFD0 HostComputer' who red spec)
-FixturePrivateIFD0=$(canary JPEG-EXIF-PRIVATE-IFD0 "$F" 'EXIF IFD0 unknown tag 0xBEEF' hidden red inferred)
-Orientation#=1
-XResolution=72
-YResolution=72
-ResolutionUnit=inches
-DateTimeOriginal=$(marker '2024:06:14 09:41:27' "$F" 'EXIF DateTimeOriginal' when amber spec)
-CreateDate=$(marker '2024:06:14 09:41:28' "$F" 'EXIF DateTimeDigitized (CreateDate)' when amber spec)
-OffsetTime=+02:00
-OffsetTimeOriginal=+02:00
-OffsetTimeDigitized=+02:00
-SubSecTimeOriginal=123
-SerialNumber=$(canary JPEG-EXIF-BODYSERIAL "$F" 'EXIF BodySerialNumber (exiftool: SerialNumber)' who red spec)
-LensSerialNumber=$(canary JPEG-EXIF-LENSSERIAL "$F" 'EXIF LensSerialNumber' who red spec)
-LensMake=Fjordcam
-LensModel=Fjordcam 6.9mm f/1.8 $(canary JPEG-EXIF-LENSMODEL "$F" 'EXIF LensModel' device amber spec)
-OwnerName=Jonas Brekkestad $(canary JPEG-EXIF-OWNER "$F" 'EXIF CameraOwnerName (exiftool: OwnerName)' who red spec)
-ImageUniqueID=$(canary JPEG-EXIF-UNIQUEID "$F" 'EXIF ImageUniqueID' hidden red spec)
-UserComment=Taken with the self timer $(canary JPEG-EXIF-USERCOMMENT "$F" 'EXIF UserComment' hidden red inferred)
-FixturePrivateExif=$(canary JPEG-EXIF-PRIVATE-EXIF "$F" 'EXIF Exif IFD unknown tag 0xBEF0' hidden red inferred)
-FixtureMakerNote<=$W/e-makernote.bin
-ExposureTime=1/250
-FNumber=1.8
-ISO=64
-FocalLength=6.9
-FocalLengthIn35mmFormat=24
-ExposureProgram#=2
-ExposureCompensation=0
-MeteringMode#=5
-ExifIFD:Flash#=16
-WhiteBalance#=0
-ColorSpace#=1
-ExifImageWidth=880
-ExifImageHeight=660
-InteropIndex=R98
-GPSLatitude=48.858370
-GPSLatitudeRef=N
-GPSLongitude=2.294481
-GPSLongitudeRef=E
-GPSAltitude=35
-GPSAltitudeRef#=0
-GPSImgDirection=312.5
-GPSImgDirectionRef=T
-GPSDateStamp=2024:06:14
-GPSTimeStamp=07:41:27
-GPSProcessingMethod=GPS
-GPSMapDatum=WGS-84
-GPSAreaInformation=Champ de Mars, Paris $(canary JPEG-GPS-AREA "$F" 'EXIF GPS IFD GPSAreaInformation' where red spec)
-ThumbnailImage<=$W/e-thumb.jpg
-XMP-dc:Creator=Astrid Holmvik $(canary JPEG-XMP-CREATOR "$F" 'XMP dc:creator' who red spec)
-XMP-xmp:CreatorTool=FjordOS Camera 14.2 $(canary JPEG-XMP-CREATORTOOL "$F" 'XMP xmp:CreatorTool' device amber spec)
-XMP-xmp:CreateDate=2024:06:14 09:41:27.456+02:00
-XMP-photoshop:City=Paris $(canary JPEG-XMP-CITY "$F" 'XMP photoshop:City' where red spec)
-XMP-xmpMM:DocumentID=xmp.did:$(canary JPEG-XMP-DOCUMENTID "$F" 'XMP xmpMM:DocumentID' hidden red spec)
-XMP-xmpMM:InstanceID=xmp.iid:$(canary JPEG-XMP-INSTANCEID "$F" 'XMP xmpMM:InstanceID' hidden red spec)
-XMP-xmpMM:History+={Action=created,When=2024:06:14 09:41:27+02:00,SoftwareAgent=FjordOS Camera 14.2}
-XMP-xmpMM:History+={Action=saved,When=2024:06:15 18:02:11+02:00,SoftwareAgent=Fjord Studio 3.1 $(canary JPEG-XMP-HISTORY "$F" 'XMP xmpMM:History stEvt:softwareAgent' hidden red spec),Changed=/}
-XMP-aux:SerialNumber=$(canary JPEG-XMP-AUXSERIAL "$F" 'XMP aux:SerialNumber' who red spec)
-XMP-exif:GPSLatitude=48.858370 N
-XMP-exif:GPSLongitude=2.294481 E
-IPTC:By-line=$(canary JPEG-IPTC-BYLINE "$F" 'IPTC By-line' who red spec)
-IPTC:City=Paris $(canary JPEG-IPTC-CITY "$F" 'IPTC City' where red spec)
-IPTC:Caption-Abstract=Sunday picnic $(canary JPEG-IPTC-CAPTION "$F" 'IPTC Caption-Abstract' hidden red inferred)
-IPTC:Keywords+=picnic
-IPTC:Keywords+=$(canary JPEG-IPTC-KEYWORD "$F" 'IPTC Keywords' hidden red inferred)
-IPTC:CopyrightNotice=(c) 2024 Astrid Holmvik $(canary JPEG-IPTC-COPYRIGHT "$F" 'IPTC CopyrightNotice' who red spec)
-PhotoshopThumbnail<=$W/e-psthumb.jpg
-Comment=Shot on a tripod $(canary JPEG-COM "$F" 'JPEG COM segment' hidden red inferred)
-Ducky:Quality=80
-Ducky:Comment=$(canary JPEG-DUCKY-COMMENT "$F" 'APP12 Ducky Comment (UTF-16)' hidden red inferred utf16)
-Ducky:Copyright=$(canary JPEG-DUCKY-COPYRIGHT "$F" 'APP12 Ducky Copyright (UTF-16)' who red spec utf16)
-ICC_Profile<=$W/e.icc
EOF
et -@ "$W/common.args" -@ "$W/e.args" "$W/e.jpg"
marker '48,51.5022N' "$F" 'XMP exif:GPSLatitude (as exiftool writes it)' where red spec raw "XMP-exif|GPS Latitude|48 deg 51' 30.13\" N" >/dev/null
marker '2024-06-14T09:41:27.456+02:00' "$F" 'XMP xmp:CreateDate' when amber spec raw 'XMP-xmp|Create Date|2024:06:14 09:41:27.456+02:00' >/dev/null
kit c2pa "$W/e-c2pa1.bin" "$W/e-c2pa2.bin" \
  "Astrid Holmvik $(canary JPEG-C2PA-AUTHOR "$F" 'APP11 C2PA, CreativeWork author (JUMBF segment 1)' hidden red spec)" \
  "FjordOS_Camera/14.2 $(canary JPEG-C2PA-GENERATOR "$F" 'APP11 C2PA, claim_generator in CBOR claim (JUMBF segment 2)' hidden red spec)"
kit blob "$W/e-app5.bin" 96 5 "$(canary JPEG-APP5 "$F" 'Unidentified APP5 segment, placed after DQT' hidden red inferred)" 'FJRD'
kit jpeg-insert "$W/e.jpg" "$W/e2.jpg" after:e2 "eb:$W/e-c2pa1.bin" "eb:$W/e-c2pa2.bin"
kit jpeg-insert "$W/e2.jpg" "$OUT/$F" before:c0 "e5:$W/e-app5.bin"

# 2. jpeg-orientation-6.jpg ###################################################
F=jpeg-orientation-6.jpg
# Drawn upright as a 480x640 portrait, then stored rotated 90 degrees anticlockwise
# as 640x480 with Orientation 6, the way a phone held upright stores it.
magick -size 480x640 xc:'#dddddd' \
  -fill '#d62828' -draw 'rectangle 0,0 119,119' \
  -fill '#2a9d3f' -draw 'rectangle 360,0 479,119' \
  -fill '#1d4ed8' -draw 'rectangle 180,520 299,639' \
  -fill '#222222' -draw 'polygon 240,160 330,300 270,300 270,460 210,460 210,300 150,300' \
  -seed 21 -attenuate 0.15 +noise Gaussian -rotate -90 "$W/o.png"
jpg "$W/o.png" "$W/o.jpg" 90
magick "$W/o.png" -resize 160x120 -strip -quality 80 "$W/o-thumb.jpg"
et -Comment="$(canary ORIENT-THUMB-COM "$F" 'EXIF IFD1 thumbnail, COM inside it' hidden red spec)" "$W/o-thumb.jpg"
cat > "$W/o.args" <<EOF
-ExifByteOrder=MM
-Orientation#=6
-Make=Fjordcam $(canary ORIENT-EXIF-MAKE "$F" 'EXIF IFD0 Make (big-endian EXIF)' device amber spec)
-Model=F5
-Artist=Astrid Holmvik $(canary ORIENT-EXIF-ARTIST "$F" 'EXIF IFD0 Artist' who red spec)
-SerialNumber=$(canary ORIENT-EXIF-BODYSERIAL "$F" 'EXIF BodySerialNumber' who red spec)
-DateTimeOriginal=$(marker '2023:11:02 15:20:44' "$F" 'EXIF DateTimeOriginal' when amber spec)
-OffsetTimeOriginal=+01:00
-ExifImageWidth=640
-ExifImageHeight=480
-GPSLatitude=52.516275
-GPSLatitudeRef=N
-GPSLongitude=13.377704
-GPSLongitudeRef=E
-GPSAltitude=34
-GPSAltitudeRef#=0
-ThumbnailImage<=$W/o-thumb.jpg
EOF
et -@ "$W/common.args" -@ "$W/o.args" "$W/o.jpg"
cp "$W/o.jpg" "$OUT/$F"

# 3. jpeg-progressive.jpg #####################################################
F=jpeg-progressive.jpg
scene "$W/p.png" 640 480 31 '#a8c5e6' '#6b7f3a'
magick "$W/p.png" -strip -interlace JPEG -quality 88 -sampling-factor 2x2 "$W/p.jpg"
cat > "$W/p.args" <<EOF
-Artist=Astrid Holmvik $(canary PROG-EXIF-ARTIST "$F" 'EXIF IFD0 Artist' who red spec)
-Software=Fjord Studio 3.1 $(canary PROG-EXIF-SOFTWARE "$F" 'EXIF IFD0 Software' device amber spec)
-DateTimeOriginal=$(marker '2023:05:20 11:12:13' "$F" 'EXIF DateTimeOriginal' when amber spec)
-GPSLatitude=41.890210
-GPSLatitudeRef=N
-GPSLongitude=12.492231
-GPSLongitudeRef=E
-GPSAreaInformation=Colosseo, Roma $(canary PROG-GPS-AREA "$F" 'EXIF GPS IFD GPSAreaInformation' where red spec)
-XMP-dc:Creator=Astrid Holmvik $(canary PROG-XMP-CREATOR "$F" 'XMP dc:creator' who red spec)
-Comment=$(canary PROG-COM "$F" 'JPEG COM segment' hidden red inferred)
EOF
et -@ "$W/common.args" -@ "$W/p.args" "$W/p.jpg"
cp "$W/p.jpg" "$OUT/$F"

# 4. jpeg-ultrahdr-like.jpg ###################################################
F=jpeg-ultrahdr-like.jpg
scene "$W/u.png" 800 600 41 '#7fb2e5' '#2f5d50'
jpg "$W/u.png" "$W/u.jpg" 90
cat > "$W/u.args" <<EOF
-Make=Fjordcam $(canary UHDR-EXIF-MAKE "$F" 'Primary image EXIF IFD0 Make' device amber spec)
-Model=F9 Pro
-Artist=Astrid Holmvik $(canary UHDR-EXIF-ARTIST "$F" 'Primary image EXIF IFD0 Artist' who red spec)
-DateTimeOriginal=$(marker '2025:01:26 20:15:30' "$F" 'Primary image EXIF DateTimeOriginal' when amber spec)
-GPSLatitude=33.856784
-GPSLatitudeRef=S
-GPSLongitude=151.215297
-GPSLongitudeRef=E
EOF
et -@ "$W/common.args" -@ "$W/u.args" "$W/u.jpg"
magick "$W/u.png" -colorspace Gray -resize 200x150 -strip -quality 85 "$W/u-gain-bare.jpg"
cat > "$W/u-gain.xml" <<EOF
<x:xmpmeta xmlns:x="adobe:ns:meta/" x:xmptk="Fjord XMP Core 1.0">
 <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
  <rdf:Description rdf:about=""
    xmlns:hdrgm="http://ns.adobe.com/hdr-gain-map/1.0/"
    xmlns:dc="http://purl.org/dc/elements/1.1/"
    hdrgm:Version="1.0" hdrgm:GainMapMin="0" hdrgm:GainMapMax="2.3" hdrgm:Gamma="1"
    hdrgm:OffsetSDR="0.015625" hdrgm:OffsetHDR="0.015625"
    hdrgm:HDRCapacityMin="0" hdrgm:HDRCapacityMax="2.3" hdrgm:BaseRenditionIsHDR="False">
   <dc:creator><rdf:Seq><rdf:li>Astrid Holmvik $(canary UHDR-GAINMAP-XMP-CREATOR "$F" 'Gain map (second JPEG after EOI, found through MPF): its own XMP dc:creator' who red spec)</rdf:li></rdf:Seq></dc:creator>
  </rdf:Description>
 </rdf:RDF>
</x:xmpmeta>
EOF
kit xmp-payload "$W/u-gain.xml" "$W/u-gain-xmp.bin"
kit jpeg-insert "$W/u-gain-bare.jpg" "$W/u-gain.jpg" after:e0 "e1:$W/u-gain-xmp.bin"
GAIN_LEN=$(stat -c %s "$W/u-gain.jpg")
cat > "$W/u-primary.xml" <<EOF
<x:xmpmeta xmlns:x="adobe:ns:meta/" x:xmptk="Fjord XMP Core 1.0">
 <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
  <rdf:Description rdf:about=""
    xmlns:hdrgm="http://ns.adobe.com/hdr-gain-map/1.0/"
    xmlns:Container="http://ns.google.com/photos/1.0/container/"
    xmlns:Item="http://ns.google.com/photos/1.0/container/item/"
    xmlns:xmp="http://ns.adobe.com/xap/1.0/"
    hdrgm:Version="1.0"
    xmp:CreatorTool="FjordOS HDR 2.0 $(canary UHDR-XMP-CREATORTOOL "$F" 'Primary image XMP xmp:CreatorTool' device amber spec)">
   <Container:Directory>
    <rdf:Seq>
     <rdf:li rdf:parseType="Resource">
      <Container:Item Item:Semantic="Primary" Item:Mime="image/jpeg"/>
     </rdf:li>
     <rdf:li rdf:parseType="Resource">
      <Container:Item Item:Semantic="GainMap" Item:Mime="image/jpeg" Item:Length="$GAIN_LEN"/>
     </rdf:li>
    </rdf:Seq>
   </Container:Directory>
  </rdf:Description>
 </rdf:RDF>
</x:xmpmeta>
EOF
kit xmp-payload "$W/u-primary.xml" "$W/u-primary-xmp.bin"
kit jpeg-insert "$W/u.jpg" "$W/u2.jpg" after:e1 "e1:$W/u-primary-xmp.bin"
kit mpf "$W/u2.jpg" "$W/u-gain.jpg" "$OUT/$F" after:e1

# 4b. Ultra HDR variants #####################################################
# The gain map of these pictures starts unticked, so each keeps it and hides one
# thing in or around it that the page must still list and remove (or, for
# iso-full and zero-pad, nothing at all: they check that a clean gain map and
# zero padding survive untouched). Built from plain JPEGs with no other
# metadata, so each file carries only its own planted strings. The gain map has
# the full hdrgm description; the photo has hdrgm:Version, a Container directory
# and an MPF index (little-endian with image IDs and layout details in mpf-extras).
jpg "$W/u.png" "$W/uv.jpg" 90
uhdr() { local f=$1 kind=$2; shift 2; kit uhdr "$W/uv.jpg" "$W/u-gain-bare.jpg" "$OUT/$f" "$kind" "$@"; }
F=jpeg-uhdr-hdrgm-extra.jpg
uhdr "$F" hdrgm-extra "$(canary UHDRV-HDRGM-SERIAL "$F" 'Photo XMP, unknown hdrgm:CameraSerialNumber next to the gain map fields' who red spec)" \
  "$(canary UHDRV-HDRGM-GPS "$F" 'Photo XMP, unknown hdrgm:GPSLatitude next to the gain map fields' where red spec)"
F=jpeg-uhdr-item-label.jpg
uhdr "$F" item-label "$(canary UHDRV-ITEM-LABEL "$F" 'Photo XMP, Item:Label on the GainMap entry of the Container directory' hidden red spec)"
F=jpeg-uhdr-apple-owner.jpg
uhdr "$F" apple-owner "$(canary UHDRV-APPLE-OWNER "$F" 'Photo XMP, HDRGainMap:OwnerName next to HDRGainMap:HDRGainMapVersion' who red spec)"
F=jpeg-uhdr-after-eoi.jpg
uhdr "$F" after-eoi "$(canary UHDRV-AFTER-EOI "$F" 'Bytes after the gain map end marker, inside its MPF size (the gain map also has an XMP toolkit name)' hidden red spec)"
F=jpeg-uhdr-bare-after-eoi.jpg
uhdr "$F" bare-after-eoi "$(canary UHDRV-BARE-AFTER-EOI "$F" 'Bytes after the end marker of a gain map with no other metadata, inside its MPF size' hidden red spec)"
F=jpeg-uhdr-mpf-tail.jpg
uhdr "$F" mpf-tail "$(canary UHDRV-MPF-TAIL "$F" 'MPF APP2, bytes after the MP entry table that no structure uses' hidden red spec)"
F=jpeg-uhdr-inner-hdrgm.jpg
uhdr "$F" inner-hdrgm "$(canary UHDRV-INNER-HDRGM "$F" 'Gain map XMP, unknown hdrgm:CameraSerialNumber' who red spec)"
F=jpeg-uhdr-iso-tail.jpg
uhdr "$F" iso-tail "$(canary UHDRV-ISO-TAIL "$F" 'Photo ISO 21496-1 APP2, bytes after its version field' hidden red spec)"
F=jpeg-uhdr-inner-mpf.jpg
uhdr "$F" inner-mpf "$(canary UHDRV-INNER-MPF "$F" 'Gain map, an MPF APP2 segment of its own with a tail' hidden red spec)"
F=jpeg-uhdr-inner-iso.jpg
uhdr "$F" inner-iso "$(canary UHDRV-INNER-ISO "$F" 'Gain map ISO 21496-1 APP2, bytes after its version field' hidden red spec)"
F=jpeg-uhdr-version-text.jpg
uhdr "$F" version-text "$(canary UHDRV-VERSION-TEXT "$F" 'Photo XMP, text inside the value of hdrgm:Version' hidden red spec)"
F=jpeg-uhdr-mpf-extras.jpg
uhdr "$F" mpf-extras "$(canary UHDRV-MPF-UID "$F" 'MPF APP2 (little-endian), B003 ImageUIDList of the photo' hidden red spec)" \
  "$(canary UHDRV-MPF-ATTR-TAG "$F" 'MPF APP2, unknown ASCII tag B2EE in the MP Attribute IFD' hidden red spec)"
F=jpeg-uhdr-dir-semantic.jpg
uhdr "$F" dir-semantic "$(canary UHDRV-DIR-SEMANTIC "$F" 'Photo XMP, Item:Semantic of a third Container directory entry that stands for no part' hidden red spec)"
F=jpeg-uhdr-dir-mime.jpg
