# 7. jpeg-extended-xmp.jpg ####################################################
F=jpeg-extended-xmp.jpg
scene "$W/x.png" 400 300 71 '#b0cde8' '#5a7a45'
jpg "$W/x.png" "$W/x.jpg" 88
X_EARLY=$(canary XXMP-EXT-ANCESTOR-500 "$F" 'Extended XMP (APP1 xmp/extension chunks), photoshop:DocumentAncestors item 500' hidden red spec)
X_LATE=$(canary XXMP-EXT-ANCESTOR-1800 "$F" 'Extended XMP, photoshop:DocumentAncestors item 1800 (past exiftool 1000-item limit)' hidden red spec)
X_CREATOR=$(canary XXMP-STD-CREATOR "$F" 'Standard XMP dc:creator' who red spec)
python3 - "$X_EARLY" "$X_LATE" "$X_CREATOR" > "$W/x.xmp" <<'EOF'
import sys
early, late, creator = sys.argv[1:4]
items = []
for i in range(2500):
    uid = 'xmp.did:%08x-%04x-4%03x-8%03x-%012x' % (0x5eed0000 + i, i * 7 % 0x10000, i % 0x1000, (i * 3) % 0x1000, i * 7919)
    if i == 500:
        uid = 'xmp.did:' + early
    if i == 1800:
        uid = 'xmp.did:' + late
    items.append('<rdf:li>%s</rdf:li>' % uid)
print('<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?>')
print('<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">'
      '<rdf:Description rdf:about="" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:photoshop="http://ns.adobe.com/photoshop/1.0/">'
      '<dc:creator><rdf:Seq><rdf:li>Astrid Holmvik %s</rdf:li></rdf:Seq></dc:creator>'
      '<photoshop:DocumentAncestors><rdf:Bag>%s</rdf:Bag></photoshop:DocumentAncestors>'
      '</rdf:Description></rdf:RDF></x:xmpmeta>' % (creator, ''.join(items)))
print('<?xpacket end="w"?>')
EOF
# -m lets exiftool copy all 2500 list items (it stops at 1000 otherwise).
et -m -tagsfromfile "$W/x.xmp" '-xmp:all' "$W/x.jpg"
cp "$W/x.jpg" "$OUT/$F"

