    xmp:CreateDate="$(marker '2024-07-21T14:03:09+01:00' "$F" 'iTXt XMP xmp:CreateDate' when amber spec raw 'XMP-xmp|Create Date|2024:07:21 14:03:09+01:00')"
    xmpMM:DocumentID="xmp.did:$(canary PNG-XMP-DOCUMENTID "$F" 'iTXt XMP xmpMM:DocumentID' hidden red spec)"
    photoshop:City="London $(canary PNG-XMP-CITY "$F" 'iTXt XMP photoshop:City' where red spec)"
