    exif:GPSLongitude="0,7.47750W">
   <dc:creator><rdf:Seq><rdf:li>Astrid Holmvik $(canary PNG-XMP-CREATOR "$F" 'iTXt XMP dc:creator' who red spec)</rdf:li></rdf:Seq></dc:creator>
