    {"type": "tEXt", "keyword": "Software", "text": "Fjord Studio 3.1 $(canary PNG-TEXT-SOFTWARE "$F" 'tEXt Software' device amber spec)"},
    {"type": "iTXt", "keyword": "XML:com.adobe.xmp", "file": "g.xmp"},
