scene "$W/r.png" 320 240 131 '#a0c4e4' '#4f7040'
jpg "$W/r.png" "$W/r.jpg" 90
et -Artist="Astrid Holmvik $(canary TRUNC-EXIF-ARTIST "$F" 'EXIF IFD0 Artist (file cut off at 2,048 bytes, inside the scan data)' who red spec)" "$W/r.jpg"
SOS=$(kit sos-offset "$W/r.jpg")
[ "$SOS" -lt 2048 ] && [ "$(stat -c %s "$W/r.jpg")" -gt 4096 ] || { echo "make-fixtures: truncated.jpg would not cut inside the scan" >&2; exit 1; }
head -c 2048 "$W/r.jpg" > "$OUT/$F"

# 14. Extra hostile structures ################################################
# jpeg-double-exif.jpg: two EXIF APP1 segments. Many readers stop at the first,
# so GPS and a second Artist hide in the second.
F=jpeg-double-exif.jpg
scene "$W/d.png" 320 240 141 '#a7c7e7' '#527347'
jpg "$W/d.png" "$W/d.jpg" 90
cp "$W/d.jpg" "$W/d-first.jpg"
cp "$W/d.jpg" "$W/d-second.jpg"
et -@ "$W/common.args" -ExifByteOrder=II -Make="Fjordcam $(canary DBLEXIF-FIRST-MAKE "$F" 'First EXIF APP1, IFD0 Make' device amber spec)" \
   -Artist="Astrid Holmvik $(canary DBLEXIF-FIRST-ARTIST "$F" 'First EXIF APP1, IFD0 Artist' who red spec)" "$W/d-first.jpg"
cat > "$W/d-second.args" <<EOF
-ExifByteOrder=MM
-Artist=Jonas Brekkestad $(canary DBLEXIF-SECOND-ARTIST "$F" 'Second EXIF APP1, IFD0 Artist' who red spec)
-GPSLatitude=51.505456
-GPSLatitudeRef=N
-GPSLongitude=0.075356
-GPSLongitudeRef=W
-GPSAreaInformation=Tower Bridge $(canary DBLEXIF-SECOND-GPS-AREA "$F" 'Second EXIF APP1, GPS GPSAreaInformation' where red spec)
EOF
et -@ "$W/common.args" -@ "$W/d-second.args" "$W/d-second.jpg"
kit jpeg-segment "$W/d-first.jpg" "$W/d-exif1.bin" e1 Exif
kit jpeg-segment "$W/d-second.jpg" "$W/d-exif2.bin" e1 Exif
kit jpeg-insert "$W/d.jpg" "$OUT/$F" after:e0 "e1:$W/d-exif1.bin" "e1:$W/d-exif2.bin"

# jpeg-ifd-cycle.jpg and jpeg-ifd-overflow.jpg: TIFF structures that loop or
# point outside the segment. A parser must stop, not hang or allocate gigabytes.
for kind in cycle overflow; do
  F=jpeg-ifd-$kind.jpg
  scene "$W/$kind.png" 320 240 151 '#a5c6e6' '#507245'
  jpg "$W/$kind.png" "$W/$kind.jpg" 90
  KIND_UP=$(printf '%s' "$kind" | tr '[:lower:]' '[:upper:]')
  kit hostile-exif "$kind" "$W/$kind-exif.bin" \
    "Astrid Holmvik $(canary "$KIND_UP-EXIF-ARTIST" "$F" "EXIF IFD0 Artist, the one well-formed tag in a hostile IFD ($kind)" who red spec)"
  kit jpeg-insert "$W/$kind.jpg" "$OUT/$F" after:e0 "e1:$W/$kind-exif.bin"
done

# 15. Free text in green details ##############################################
# A colour profile and a technical XMP field are green and kept by default, so a
# name hidden in them must be offered as its own red detail and go by default,
# with the colours unchanged.
F=jpeg-icc-text.jpg
scene "$W/it.png" 320 240 161 '#a8c8e6' '#4c6f42'
jpg "$W/it.png" "$W/it.jpg" 90
kit icc-text "$ICC_SRC" "$W/it.icc" mluc \
  "desc=Astrid Holmvik $(canary ICCTEXT-JPEG-DESC "$F" 'ICC profile (APP2), mluc description' hidden red spec utf16)" \
  "cprt=Copyright Astrid Holmvik $(canary ICCTEXT-JPEG-CPRT "$F" 'ICC profile (APP2), mluc copyright' hidden red spec utf16)" \
  "dmnd=Astrid Holmvik $(canary ICCTEXT-JPEG-DMND "$F" 'ICC profile (APP2), mluc device manufacturer description' hidden red spec utf16)"
et "-ICC_Profile<=$W/it.icc" "$W/it.jpg"
cp "$W/it.jpg" "$OUT/$F"

F=png-icc-text.png
magick "$W/it.png" -strip "PNG24:$W/ip-base.png"
kit icc-text "$ICC_SRC" "$W/ip.icc" ascii \
  "desc=Astrid Holmvik $(canary ICCTEXT-PNG-DESC "$F" 'iCCP profile (compressed), description' hidden red spec zlib)" \
  "cprt=Copyright Astrid Holmvik $(canary ICCTEXT-PNG-CPRT "$F" 'iCCP profile (compressed), copyright' hidden red spec zlib)"
cat > "$W/ip.json" <<EOF
{
  "base": "$W/ip-base.png",
  "out": "$OUT/$F",
  "before": [
    {"type": "iCCP", "name": "Astrid $(canary ICCTEXT-PNG-NAME "$F" 'iCCP profile name field (a name, not a known profile name)' hidden red spec)", "file": "ip.icc"}
  ]
}
EOF
kit png-build "$W/ip.json"

F=webp-icc-text.webp
magick "$W/it.png" -strip -quality 80 -define webp:lossless=false -define webp:method=4 "$W/iw.webp"
kit icc-text "$ICC_SRC" "$W/iw.icc" ascii \
  "cprt=Copyright Astrid Holmvik $(canary ICCTEXT-WEBP-CPRT "$F" 'ICCP chunk, copyright' hidden red spec)" \
  "dmdd=Astrid Holmvik $(canary ICCTEXT-WEBP-DMDD "$F" 'ICCP chunk, device model description' hidden red spec)"
et "-ICC_Profile<=$W/iw.icc" "$W/iw.webp"
cp "$W/iw.webp" "$OUT/$F"

F=heic-icc-text.heic
kit icc-text "$ICC_SRC" "$W/ih.icc" mluc \
  "desc=Astrid Holmvik $(canary ICCTEXT-HEIC-DESC "$F" 'colr property (ICC profile), mluc description' hidden red spec utf16)" \
  "cprt=Copyright Astrid Holmvik $(canary ICCTEXT-HEIC-CPRT "$F" 'colr property (ICC profile), mluc copyright' hidden red spec utf16)"
magick "$W/it.png" -profile "$W/ih.icc" -depth 8 -quality 60 "$OUT/$F"

F=jpeg-green-xmp.jpg
jpg "$W/it.png" "$W/ix.jpg" 90
cat > "$W/ix.xml" <<EOF
<x:xmpmeta xmlns:x="adobe:ns:meta/">
 <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
  <rdf:Description rdf:about=""
    xmlns:xmp="http://ns.adobe.com/xap/1.0/"
    xmlns:photoshop="http://ns.adobe.com/photoshop/1.0/"
    xmlns:GPano="http://ns.google.com/photos/1.0/panorama/"
    xmp:Rating="Astrid Holmvik $(canary GREENXMP-RATING "$F" 'XMP xmp:Rating holding text instead of a number' hidden red spec)"
    photoshop:ICCProfile="Astrid Holmvik $(canary GREENXMP-ICCPROFILE "$F" 'XMP photoshop:ICCProfile holding a name, not a known profile name' hidden red spec)"
    photoshop:ColorMode="3"
    GPano:ProjectionType="$(canary GREENXMP-GPANO-PROJECTION "$F" 'XMP GPano:ProjectionType holding text, not one of the projection names' hidden red spec)"
    GPano:PoseHeadingDegrees="12.5"/>
 </rdf:RDF>
</x:xmpmeta>
EOF
kit xmp-payload "$W/ix.xml" "$W/ix-xmp.bin"
kit jpeg-insert "$W/ix.jpg" "$OUT/$F" after:e0 "e1:$W/ix-xmp.bin"

# Checks and reports ##########################################################
rm -rf "$W"
kit verify "$REG" "$OUT"
LARGE=$(stat -c %s "$OUT/jpeg-large.jpg")
[ "$LARGE" -ge 6000000 ] || { echo "make-fixtures: jpeg-large.jpg is only $LARGE bytes" >&2; exit 1; }
[ "$(stat -c %s "$OUT/truncated.jpg")" -eq 2048 ] || { echo "make-fixtures: truncated.jpg is not 2,048 bytes" >&2; exit 1; }
kit visibility "$REG" "$OUT" "$OUT/exiftool" "$OUT/exiftool-visibility.tsv"
kit report "$REG" "$OUT/exiftool-visibility.tsv" "$OUT/canaries-tables.md"

# CANARIES.md must document every planted string.
MISSING=0
while IFS=$'\t' read -r s _; do
  [ "$s" = string ] && continue
  grep -qF -e "$s" "$HERE/CANARIES.md" 2>/dev/null || { echo "make-fixtures: not in CANARIES.md: $s" >&2; MISSING=1; }
done < "$REG"
[ "$MISSING" = 0 ] || echo "make-fixtures: CANARIES.md is stale; compare it with out/canaries-tables.md" >&2

(cd "$OUT" && find . -maxdepth 1 -type f ! -name '.*' ! -name SHA256SUMS -printf '%P\n' | sort | xargs sha256sum > SHA256SUMS)
echo "make-fixtures: done. Fixtures in $OUT"
(cd "$OUT" && find . -maxdepth 1 -type f \( -name '*.jpg' -o -name '*.png' -o -name '*.webp' -o -name '*.heic' -o -name '*.pdf' \) -printf '%10s  %P\n' | sort -k2)
